import {createWildlife} from './wildlife-model.js';
import {terrainHeight} from './world.js';

export function makeDeer(THREE,scene,trees){
 const simulation=createWildlife(trees),sphere=new THREE.SphereGeometry(1,10,8),limb=new THREE.CylinderGeometry(.065,.045,1,7),antlerGeo=new THREE.CylinderGeometry(.015,.04,1,5);
 const materials={coat:new THREE.MeshStandardMaterial({color:0xbf7940,roughness:.95}),cream:new THREE.MeshStandardMaterial({color:0xf5dfb8,roughness:1}),dark:new THREE.MeshStandardMaterial({color:0x342b25,roughness:.8}),antler:new THREE.MeshStandardMaterial({color:0xd2b68b,roughness:1})};
 const occluders=[];
 function oval(parent,material,x,y,z,sx,sy,sz){const mesh=new THREE.Mesh(sphere,materials[material]);mesh.position.set(x,y,z);mesh.scale.set(sx,sy,sz);parent.add(mesh);occluders.push(mesh);return mesh;}
 function stick(parent,a,b){const start=new THREE.Vector3(...a),end=new THREE.Vector3(...b),v=end.clone().sub(start),mesh=new THREE.Mesh(antlerGeo,materials.antler);mesh.position.copy(start).add(end).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v.clone().normalize());mesh.scale.y=v.length();parent.add(mesh);}
 // Small contact shadows follow the animals without recomputing forest shadows.
 const shadowCanvas=document.createElement('canvas');shadowCanvas.width=shadowCanvas.height=64;const ctx=shadowCanvas.getContext('2d'),gradient=ctx.createRadialGradient(32,32,3,32,32,32);gradient.addColorStop(0,'rgba(15,30,15,.3)');gradient.addColorStop(1,'rgba(15,30,15,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);const shadowTexture=new THREE.CanvasTexture(shadowCanvas),shadowMat=new THREE.MeshBasicMaterial({map:shadowTexture,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1});
 const actors=simulation.animals.map(animal=>{const root=new THREE.Group();root.scale.setScalar(animal.scale);scene.add(root);const body=new THREE.Group();root.add(body);oval(body,'coat',0,1.26,0,.38,.46,.82);oval(body,'cream',0,1.1,.03,.3,.25,.67);oval(body,'cream',0,1.35,-.73,.24,.28,.1);const tail=oval(body,'coat',0,1.51,-.87,.11,.22,.12);tail.rotation.x=-.6;
  const neckPivot=new THREE.Group();neckPivot.position.set(0,1.4,.55);body.add(neckPivot);const neck=oval(neckPivot,'coat',0,.3,.16,.2,.5,.23);neck.rotation.x=.4;oval(neckPivot,'cream',0,.24,.32,.12,.34,.06);const head=new THREE.Group();head.position.set(0,.67,.31);neckPivot.add(head);oval(head,'coat',0,0,.1,.18,.2,.29);oval(head,'coat',0,-.09,.34,.12,.13,.22);oval(head,'dark',0,-.08,.51,.1,.075,.07);
  for(const side of [-1,1]){oval(head,'dark',side*.16,.045,.24,.035,.04,.035);const ear=oval(head,'coat',side*.22,.23,.015,.105,.27,.065);ear.rotation.z=side*-.6;const inner=oval(ear,'cream',0,0,.85,.6,.8,.2);inner.position.z=.85;}
  if(animal.antlers)for(const side of [-1,1]){stick(head,[side*.12,.16,-.05],[side*.22,.66,-.2]);stick(head,[side*.22,.66,-.2],[side*.36,1.02,-.12]);stick(head,[side*.23,.65,-.2],[side*.46,.85,.03]);stick(head,[side*.18,.44,-.15],[side*.35,.65,.16]);}
  const legs=[];for(const side of [-1,1])for(const front of [-1,1]){const hip=new THREE.Group();hip.position.set(side*.26,1.12,front*.53);body.add(hip);const upper=new THREE.Mesh(limb,materials.coat);upper.position.y=-.295;upper.scale.y=.59;hip.add(upper);const knee=new THREE.Group();knee.position.y=-.59;hip.add(knee);const lower=new THREE.Mesh(limb,materials.coat);lower.position.y=-.295;lower.scale.set(.67,.59,.67);knee.add(lower);oval(knee,'dark',0,-.59,.025,.065,.06,.09);legs.push({hip,knee,side,front});}
  const shadow=new THREE.Mesh(new THREE.PlaneGeometry(2.8,3.7),shadowMat);shadow.rotation.x=-Math.PI/2;scene.add(shadow);return{root,body,neckPivot,tail,legs,shadow};});
 let elapsed=0;
 function update(dt,reducedMotion=false,camera=null){simulation.update(dt);elapsed+=dt;simulation.animals.forEach((animal,i)=>{const actor=actors[i],scale=animal.scale;actor.root.position.set(animal.x,animal.y,animal.z);actor.root.rotation.y=animal.heading;actor.root.visible=!camera||camera.position.distanceTo(actor.root.position)<190;actor.shadow.visible=actor.root.visible;if(!actor.root.visible)return;const phase=animal.distance*5,walk=animal.moving?1:0,bob=reducedMotion?0:Math.sin(phase*2)*.018*walk;actor.body.position.y=bob;
   const graze=animal.mode==='graze'?1:0;actor.neckPivot.rotation.x+=(graze?2.05-actor.neckPivot.rotation.x:-actor.neckPivot.rotation.x)*Math.min(1,dt*2);actor.neckPivot.rotation.z=reducedMotion?0:Math.sin(elapsed*.7+animal.phase)*.045;actor.tail.rotation.z=reducedMotion?0:Math.sin(elapsed*1.6+animal.phase)*.12;
   for(const leg of actor.legs){const cycle=phase+(leg.side===leg.front?0:Math.PI),swing=Math.sin(cycle)*walk,footZ=leg.hip.position.z+swing*.24,footX=leg.hip.position.x,c=Math.cos(animal.heading),s=Math.sin(animal.heading),wx=animal.x+(footX*c+footZ*s)*scale,wz=animal.z+(-footX*s+footZ*c)*scale,ground=(terrainHeight(wx,wz)-animal.y)/scale;const footY=ground+Math.max(0,Math.cos(cycle))*.13*walk+.055;const dy=leg.hip.position.y+bob-footY,dz=footZ-leg.hip.position.z,dist=Math.min(1.175,Math.max(.1,Math.hypot(dy,dz))),base=Math.atan2(-dz,dy),bend=Math.acos(dist/1.18)*(leg.front===1?-1:1);leg.hip.rotation.x=base+bend;leg.knee.rotation.x=-2*bend;}
   actor.shadow.position.set(animal.x,animal.y+.035,animal.z);actor.shadow.rotation.z=-animal.heading;actor.shadow.scale.setScalar(scale);
  });}
 update(0);return{update,occluders,count:actors.length};
}
